void Interface::showVoicePopup(){
    if(showVoicePopup_)ImGui::OpenPopup("Test voices");
    if(!ImGui::BeginPopupModal("Test voices",nullptr,ImGuiWindowFlags_AlwaysAutoResize))return;
    auto pool=parseVoicePool(settings_.voicePool);
    if(pool.empty())ImGui::TextDisabled("The voice pool is empty. Add comma-separated voice names first.");
    int removeIndex=-1;
    for(size_t index=0;index<pool.size();++index){ImGui::PushID(static_cast<int>(index));ImGui::TextUnformatted(pool[index].c_str());ImGui::SameLine(260);
        if(ImGui::Button("Play"))speech_.speak("OpenATC radio check. Reading you five.",engine_.endpoint(),0,settings_.controllerVolume,pool[index],0,false,"standard");
        ImGui::SameLine();if(ImGui::Button("Remove"))removeIndex=static_cast<int>(index);ImGui::PopID();}
    if(removeIndex>=0){pool.erase(pool.begin()+removeIndex);std::string joined;for(size_t index=0;index<pool.size();++index){if(index)joined+=", ";joined+=pool[index];}settings_.voicePool=joined;}
    ImGui::Separator();ImGui::TextDisabled("%s",speech_.status().c_str());
    if(ImGui::Button("Close",{120,0})){showVoicePopup_=false;ImGui::CloseCurrentPopup();}
    ImGui::EndPopup();
}
